-- etl-craft: convert-target-state
ALTER TABLE AUD_TARGET_HASH_VERSION ADD COLUMN TARGET_CATALOG_NAME VARCHAR;
ALTER TABLE AUD_TARGET_HASH_VERSION ADD COLUMN TARGET_SCHEMA_NAME VARCHAR;
ALTER TABLE AUD_TARGET_HASH_VERSION ADD COLUMN TARGET_TABLE_NAME VARCHAR;
UPDATE AUD_TARGET_HASH_VERSION SET TARGET_CATALOG_NAME = split_part(TARGET_OBJECT, '.', 1), TARGET_SCHEMA_NAME = split_part(TARGET_OBJECT, '.', 2), TARGET_TABLE_NAME = split_part(TARGET_OBJECT, '.', 3);
ALTER TABLE AUD_TARGET_HASH_VERSION DROP COLUMN TARGET_OBJECT;
ALTER TABLE AUD_TARGET_HASH_VERSION ALTER COLUMN TARGET_CATALOG_NAME SET NOT NULL, ALTER COLUMN TARGET_SCHEMA_NAME SET NOT NULL, ALTER COLUMN TARGET_TABLE_NAME SET NOT NULL;
ALTER TABLE AUD_TARGET_HASH_VERSION ADD CONSTRAINT pk_target_hash_version PRIMARY KEY (TARGET_CATALOG_NAME, TARGET_SCHEMA_NAME, TARGET_TABLE_NAME);
ALTER TABLE AUD_TARGET_VIEW_STATEMENT ADD COLUMN TARGET_CATALOG_NAME VARCHAR;
ALTER TABLE AUD_TARGET_VIEW_STATEMENT ADD COLUMN TARGET_SCHEMA_NAME VARCHAR;
ALTER TABLE AUD_TARGET_VIEW_STATEMENT ADD COLUMN TARGET_TABLE_NAME VARCHAR;
UPDATE AUD_TARGET_VIEW_STATEMENT SET TARGET_CATALOG_NAME = split_part(TARGET_OBJECT, '.', 1), TARGET_SCHEMA_NAME = split_part(TARGET_OBJECT, '.', 2), TARGET_TABLE_NAME = split_part(TARGET_OBJECT, '.', 3);
ALTER TABLE AUD_TARGET_VIEW_STATEMENT DROP COLUMN TARGET_OBJECT;
ALTER TABLE AUD_TARGET_VIEW_STATEMENT ALTER COLUMN TARGET_CATALOG_NAME SET NOT NULL, ALTER COLUMN TARGET_SCHEMA_NAME SET NOT NULL, ALTER COLUMN TARGET_TABLE_NAME SET NOT NULL;
ALTER TABLE AUD_TARGET_VIEW_STATEMENT ADD CONSTRAINT pk_target_view_statement PRIMARY KEY (TARGET_CATALOG_NAME, TARGET_SCHEMA_NAME, TARGET_TABLE_NAME);
ALTER TABLE AUD_BUSINESS_RULES_RESULTS ADD COLUMN TARGET_CATALOG_NAME VARCHAR;
ALTER TABLE AUD_BUSINESS_RULES_RESULTS ADD COLUMN TARGET_SCHEMA_NAME VARCHAR;
ALTER TABLE AUD_BUSINESS_RULES_RESULTS ADD COLUMN TARGET_TABLE_NAME VARCHAR;
UPDATE AUD_BUSINESS_RULES_RESULTS SET TARGET_CATALOG_NAME = CASE WHEN array_length(string_to_array(TARGET_TABLE, '.'), 1) = 3 THEN split_part(TARGET_TABLE, '.', 1) END, TARGET_SCHEMA_NAME = CASE WHEN array_length(string_to_array(TARGET_TABLE, '.'), 1) = 3 THEN split_part(TARGET_TABLE, '.', 2) ELSE split_part(TARGET_TABLE, '.', 1) END, TARGET_TABLE_NAME = CASE WHEN array_length(string_to_array(TARGET_TABLE, '.'), 1) = 3 THEN split_part(TARGET_TABLE, '.', 3) ELSE split_part(TARGET_TABLE, '.', 2) END;
ALTER TABLE AUD_BUSINESS_RULES_RESULTS DROP COLUMN TARGET_TABLE;
ALTER TABLE AUD_BUSINESS_RULES_RESULTS ALTER COLUMN TARGET_SCHEMA_NAME SET NOT NULL, ALTER COLUMN TARGET_TABLE_NAME SET NOT NULL;
